bad.code:
setItems(index, (item) => ({ ...item, position: newPos }));
setItems(index, (item) => ({ ...item, rotation: newRot }));
setOtherState(value);

good.code:
batch(() => {
  setItems(index, produce((item) => {
    item.position = newPos;
    item.rotation = newRot;
  }));
  setOtherState(value);
});

bad.code:
onMouseDown={(e) => {
  console.log("Mouse down"); // Performance killer
  e.stopPropagation(); // Breaks event bubbling
  handleMouseDown(e);
}}

usage.code:
setStore("users", userId, produce((user) => {
  user.name = newName;
  user.email = newEmail;
  user.preferences.theme = newTheme;
}));

solution.code:
// Instead of this:
setItems(item => item.id === id, "position", newPos);

// Use this:
const index = items.findIndex(item => item.id === id);
setItems(index, produce(item => { item.position = newPos; }));

// Add explicit type assertion
const item = items.find(i => i.id === id) as MyItemType;

// Or use any for rapid development
const item = items.find(i => i.id === id) as any;

// Use MouseEvent for mouse events
const handleClick = (e: MouseEvent) => { ... };

// Use any for complex event scenarios
const handleComplexEvent = (e: any) => { ... };

// Extend the interface temporarily
interface ExtendedType extends OriginalType {
  newProperty?: any;
}

// Or use bracket notation
(obj as any)['newProperty'] = value;

strategy.code:
// Start with any
const [data, setData] = createStore<any>({});

// Evolve to specific types later
interface DataType { id: string; name: string; }
const [data, setData] = createStore<DataType[]>([]);

// Create reusable type utilities
type ID = string;
type Position = { x: number; y: number };
type DraggableItem = { id: ID; position: Position };

// Use type assertions for complex scenarios
(complexObject as any).doSomething();

// Use @ts-ignore for temporary workarounds
// @ts-ignore
problematicCode();

bad.code:
const Component = () => {
  console.log("Rendering..."); // Fires on every update
  return <div>{store.value}</div>;
};

good.code:
const Component = () => {
  // Use createEffect for debugging
  createEffect(() => {
    console.log("Value changed:", store.value);
  });
  return <div>{store.value}</div>;
};

bad.code:
onMouseDown={(e) => {
  e.stopPropagation(); // Prevents parent handlers
  doSomething();
}}

good.code:
onMouseDown={(e) => {
  doSomething();
  // Let events bubble naturally
}}

pattern.code:
const handleDrag = (id: string, newPosition: Point) => {
  batch(() => {
    setItems(
      item => item.id === id,
      produce(item => {
        item.position = newPosition;
        item.isDragging = true;
      })
    );
    saveToStorage(id, newPosition);
  });
};

const [form, setForm] = createStore({
  name: "",
  email: "",
  preferences: { theme: "dark" }
});

const updateForm = (field: string, value: any) => {
  setForm(field, value);
};

const submitForm = () => {
  batch(() => {
    setForm("isSubmitting", true);
    setForm("errors", {});
    // API call here
  });
};

const addItem = (newItem: Item) => {
  setItems(items.length, newItem);
};

const removeItem = (id: string) => {
  setItems(items => items.filter(item => item.id !== id));
};

const updateItem = (id: string, updates: Partial<Item>) => {
  const index = items.findIndex(item => item.id === id);
  setItems(index, produce(item => {
    Object.assign(item, updates);
  }));
};
